const MING=[["顺天府", "北直隶", 39.9, 116.4, "今北京。永乐元年改北平府为顺天府。"], ["保定府", "北直隶", 38.87, 115.46, "今保定。"], ["河间府", "北直隶", 38.45, 116.1, "今河间。"], ["真定府", "北直隶", 38.15, 114.57, "今正定。明代赵州是真定府属州。"], ["顺德府", "北直隶", 37.07, 114.5, "今邢台。"], ["广平府", "北直隶", 36.68, 114.7, "今邯郸永年广府城。"], ["大名府", "北直隶", 36.29, 115.15, "今大名。"], ["永平府", "北直隶", 39.89, 118.87, "今卢龙。"], ["赵州", "真定府属州", 37.756, 114.776, "今赵县。"], ["太原府", "山西", 37.87, 112.55, "今太原。"], ["平阳府", "山西", 36.09, 111.52, "今临汾。洪洞县属平阳府。"], ["大同府", "山西", 40.08, 113.3, "今大同。"], ["潞州", "山西", 36.19, 113.11, "今长治。嘉靖八年升潞安府。"], ["泽州", "山西", 35.49, 112.85, "今晋城。"], ["汾州", "山西", 37.27, 111.78, "今汾阳。万历二十三年升汾州府。"], ["沁州", "山西", 36.76, 112.7, "今沁县。"], ["辽州", "山西", 37.06, 113.37, "今左权。"]];
